"""Build a derived-only GitHub preview; never copy originals, raw latent tensors or blinding keys."""
import argparse
import ast
import csv
import json
from pathlib import Path
import shutil
import sys
from PIL import Image
BASE=Path('/n/fs/goose/experiments/mid0_sae_selectivity');sys.path.insert(0,str(BASE))
from run import atomic_json,csv_write,digest

def main():
    p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();run=a.run.resolve();out=a.output.resolve()
    out.mkdir(parents=True,exist_ok=False)
    for d in ('figures','results','evaluations','code','review_preview'):(out/d).mkdir()
    names=['01_donor_activation_heatmaps','02_pattern_controls','03_paired_black_man','03_paired_east_asian_man','04_facial_hair_vs_norm',
           '05_face_detection_vs_norm','06_spatial_concentration','07_per_donor_recipient']
    for name in names:
        for suffix in ('.png','.pdf'):
            src=run/'figures'/(name+suffix);dest=out/'figures'/src.name
            if name.startswith('03_') and suffix=='.png':
                with Image.open(src) as im:
                    preview=im.copy();preview.thumbnail((2100,1800),Image.Resampling.LANCZOS);preview.save(dest)
            else:shutil.copy2(src,dest)
    for name in ('all_generations.csv','summary_statistics.csv','paired_comparisons.csv','semantic_attribute_changes.csv','per_image_results.csv',
                 'naturalness.csv','activity_stratified_descriptive.csv','face_detection_seed_wilson.csv','observed_proxy_summary.csv','failures_and_missingness.csv','research_summary.md'):
        shutil.copy2(run/'results'/name,out/'results'/name)
    for name in ('demographic_predictions.csv','face_validity.csv','image_metrics.csv','human_labels.csv','segmentation_results.csv'):
        shutil.copy2(run/'evaluations'/name,out/'evaluations'/name)
    for name in ('review_form.csv','INSTRUCTIONS.md','page_01.png','page_02.png'):
        shutil.copy2(run/'evaluations/blinded_review'/name,out/'review_preview'/name)
    cfg=json.loads((run/'config/experiment_config.json').read_text())
    csv_write(out/'configuration.csv',[dict(key=k,value=json.dumps(v)) for k,v in cfg.items()])
    modelrows=json.loads((run/'config/generator_checkpoint_manifest.json').read_text())+json.loads((run/'config/input_manifest.json').read_text())
    csv_write(out/'source_checkpoint_hashes.csv',modelrows)
    shutil.copy2(run/'config/context_activity.csv',out/'context_activity.csv')
    for src in Path(__file__).parent.glob('*'):
        if src.suffix in ('.py','.sbatch'):shutil.copy2(src,out/'code'/src.name)
    # Export the reused storage utilities, without the older unrelated generation CLI/checkpoint defaults.
    source=(BASE/'run.py').read_text();tree=ast.parse(source)
    helpers=['digest','atomic_json','csv_write','events','record','index','inventory']
    exported='import csv,hashlib,json,os\nfrom pathlib import Path\nROOT=Path(os.environ.get("SAE_PROJECT_ROOT","/n/fs/goose"))\nBLOCK="unet.mid_block.attentions.0"\n\n'
    for node in tree.body:
        if isinstance(node,ast.FunctionDef) and node.name in helpers:exported+=ast.get_source_segment(source,node)+'\n\n'
    (out/'code/run.py').write_text(exported)
    (out/'code/additive.py').write_text('from run import ROOT\nCHECKPOINT=ROOT/"layers/runs/mid0_sae_face_001/sae"\nEXPECTED_HASH="cbb3a0a2d0c43c822c7ba97a494de38ae56ea25401a8d31484ffa32e7cc329a6"\n')
    (out/'code/README.md').write_text('The spatial scripts are source copies of this experiment. run.py exports the exact reused storage utility function bodies without any older generation CLI; additive.py exports only the selected face-SAE constants. No alternate SAE or generator is loaded. Scripts expect the existing /n/fs/goose research workspace, its local model cache, and previously saved baseline archives. Full executed generation snapshots are preserved locally in config/source/; evaluation snapshots are in config/evaluation_source/. See the permanent run README for exact commands. Code publication does not include model weights or raw experiment archives.\n')
    table=list(csv.DictReader((run/'results/observed_proxy_summary.csv').open()))
    readme=f'''# Spatial activation-pattern transfer — feature 4228\n\n**Completed: 200 matched edited conditions, 10 generated no-op replays, and 10 reused baselines.** Full original images, latent dictionaries, spatial maps and applied block-output tensors are preserved permanently in:\n\n`{run}`\n\nThis GitHub report contains derived figures, CSVs, code and image previews only. Raw tensor archives and original generations are not duplicated here.\n\n## What was tested\n\nOne face-fine-tuned SAE (`layers/runs/mid0_sae_face_001/sae`, SHA-256 `cbb3a0a2d0c43c822c7ba97a494de38ae56ea25401a8d31484ffa32e7cc329a6`), one layer (`unet.mid_block.attentions.0`), and the same frozen single-step SDXL Turbo generator. No training, alternative SAE or alternative diffusion model.\n\nTwo naturally active Black-man donor maps (seeds30,31;23 and8 nonzero spatial cells) are added to paired Black-man and East-Asian-man contexts at seeds30–34. Conditions: natural maps, uniform patterns, three exact spatial permutations per donor (shuffle seeds1729,2718,3141), and recipient landmark-derived lower-face patterns. Uniform/localized conditions are shared across donors. Unscaled shuffled maps preserve the exact donor value distribution. Coefficients are subsequently matched against the actual fp16-applied block-output norm; tiny coefficient differences across layouts are recorded.\n\nTargets: **42.5242 and65.1363**. All200 edits are within0.5%; worst relative error is approximately **0.000627%**. No clipping, hidden map normalization or Top-K reapplication.\n\n**Activity is checked cell by cell.** East-Asian-man seed33 has two nonzero cells; seeds30,31,32,34 are completely inactive. Black-man seeds32 and34 are also inactive. None are silently relabeled or discarded.\n\n## Donors and spatial controls\n\n![Original donor heatmaps](figures/01_donor_activation_heatmaps.png)\n\n![Natural, uniform, shuffled and localized patterns](figures/02_pattern_controls.png)\n\nDonor maps are transferred in absolute image-grid coordinates without pose alignment or warping. Lower-face masks use the existing MediaPipe extended-chin ROI and float BOX area averaging from512×512 to16×16, retaining fractional weights. This is geometric localization, not beard segmentation.\n\n## Paired generation previews\n\nEach row is one recipient seed. Columns show baseline, uniform, natural donor30, natural donor31, donor30 shuffled with seed1729, and localized intervention. All edited columns use applied L2 target65.1363. The displayed shuffle seed was fixed before evaluating outcomes. PNGs are resized viewing derivatives of full figures; full-resolution PDF figures are also included. Original generated512px PNGs remain untouched in the permanent archive.\n\n![East-Asian-man paired previews](figures/03_paired_east_asian_man.png)\n\n![Black-man paired previews](figures/03_paired_black_man.png)\n\n## What the measurements establish\n\nEqual applied norms produce markedly different sparse-support shifts. At target65.1363, uniform edits exceed k=10 support at about99.8% of spatial cells in East-Asian-man contexts, compared with6.0% for natural-pattern edits. Thus matching L2 alone does not make interventions equally natural.\n\n| Context | Method | Pixel MAE | Lower-face fraction of image change | Spatial cells beyond k=10 |\n|---|---|---:|---:|---:|\n'''
    for r in table:readme+=f"| {r['group']} | {r['method']} | {float(r['mean_pixel_mae']):.3f} | {float(r['mean_lowerface_change_fraction']):.3f} | {100*float(r['mean_fraction_positions_exceeding_topk']):.1f}% |\n"
    readme+='''\nFor East-Asian-man contexts at target65.1363, natural minus shuffled lower-face change concentration is **+0.00784**, with95% seed-bootstrap interval **[−0.01036,0.02715]** and exact two-sided sign-flip p=0.5. This five-seed experiment does **not establish a clear localization advantage** for the natural pattern over shuffled patterns. These are image-change measures, not facial-hair measurements.\n\n![Spatial concentration](figures/06_spatial_concentration.png)\n\n![Per-donor and recipient comparisons](figures/07_per_donor_recipient.png)\n\nAll220 conditions had MediaPipe detections and FairFace probability vectors. Detection does not establish structural validity; demographics are classifier predictions of perceived appearance, not ground-truth identities. The main detection figure uses95% Wilson intervals over five seed-level all-images-detected events; a5/5 detection result has a lower bound of about0.566.\n\n![Face detection proxy](figures/05_face_detection_vs_norm.png)\n\n## Facial-hair effects remain unmeasured\n\nNo validated facial-hair classifier or reviewed beard segmenter was available. The existing SAM probes are class-agnostic and are not beard-accuracy measurements. We therefore prepared **27 blinded review sheets covering200 edits and10 no-op pairs**, with facial-hair presence, full-beard presence, estimated coverage, structural validity and artifact fields. No human ratings have been supplied yet, and no semantic values are invented.\n\n![Explicitly pending facial-hair analysis](figures/04_facial_hair_vs_norm.png)\n\n[Blinded instructions and preview sheets](review_preview/) and the [review form](review_preview/review_form.csv) are included. All27 pages and the separate blinding key remain in the local archive; the key is deliberately withheld here. Rerun analyze.py after ratings are entered, without regenerating any images.\n\n## Statistics, reproducibility and limits\n\nComparisons are paired within recipient seed and fixed donor. Shuffle/donor replicates are averaged before seed-level inference; repeated images do not count as independent seeds. Intervals enumerate the empirical seed-cluster bootstrap (all5^5 resamples); sign-flip tests enumerate all2^5 assignments. Five seeds and two fixed donors support exploratory analysis, not a confirmatory or multiplicity-adjusted claim. Activity-stratified descriptive results are provided separately.\n\nThe smoke test passed with24 edited conditions and two pixel-identical no-op replays. Seed30 subsequently resumed with exactly42 total generation attempts, confirming that smoke images were not regenerated. Full condition plans, versioned code snapshots, environments, per-attempt journals, all raw data and the output-file hash manifest remain in the permanent experiment directory.\n\n[Paired comparisons](results/paired_comparisons.csv), [per-image results](results/per_image_results.csv), [naturalness measurements](results/naturalness.csv), [per-image demographic confidences](evaluations/demographic_predictions.csv), [configuration](configuration.csv), [checkpoint hashes](source_checkpoint_hashes.csv), [code](code/) and [research summary](results/research_summary.md).\n\nThis experiment establishes a controlled comparison of spatial layouts and quantifies their distinct support shifts. **It does not yet establish that feature4228 controls beards, nor demographic causal specificity.** Blinded semantic ratings are the next required evidence.\n'''
    (out/'README.md').write_text(readme)
    csv_write(out/'manifest.csv',[dict(path=str(p.relative_to(out)),bytes=p.stat().st_size,sha256=digest(p)) for p in sorted(out.rglob('*')) if p.is_file()])
    print(out)
if __name__=='__main__':main()
